// // // // // // // // // // // // // // // // // // // // //     const rows: T[][] = [];
// // // // // // // // // // // // // // // // // // // // //     for (let i = 0; i < arr.length; i += size) rows.push(arr.slice(i, i + size));
// // // // // // // // // // // // // // // // // // // // //     return rows;
// // // // // // // // // // // // // // // // // // // // //   };

